<?php use App\Core\CSRF; ?>
<div class="d-flex flex-wrap justify-content-between gap-2 mb-4"><div><a href="/vehicles" class="small">← Veículos</a><h1 class="h3 mb-1"><?=htmlspecialchars(trim(($vehicle['make']??'').' '.$vehicle['model']))?></h1><p class="text-secondary mb-0"><?=htmlspecialchars($vehicle['plate']??'Sem placa')?> · <?=htmlspecialchars($vehicle['customer_name'])?> · <?=htmlspecialchars($vehicle['customer_phone'])?></p></div><a class="btn btn-primary" href="/auto/bookings/create">Novo atendimento</a></div>
<div class="row g-4"><div class="col-lg-4"><div class="card mb-4"><div class="card-header"><strong>Ficha do veículo</strong></div><div class="card-body"><form method="post" action="/vehicles/<?=(int)$vehicle['id']?>/update" class="row g-2"><?=CSRF::field()?><input type="hidden" name="customer_id" value="<?=(int)$vehicle['customer_id']?>"><div class="col-6"><label class="form-label">Placa</label><input name="plate" value="<?=htmlspecialchars($vehicle['plate']??'')?>" class="form-control"></div><div class="col-6"><label class="form-label">Marca</label><input name="make" value="<?=htmlspecialchars($vehicle['make']??'')?>" class="form-control"></div><div class="col-8"><label class="form-label">Modelo</label><input name="model" value="<?=htmlspecialchars($vehicle['model'])?>" class="form-control" required></div><div class="col-4"><label class="form-label">Ano</label><input type="number" name="year" value="<?=htmlspecialchars((string)($vehicle['year']??''))?>" class="form-control"></div><div class="col-6"><label class="form-label">Cor</label><input name="color" value="<?=htmlspecialchars($vehicle['color']??'')?>" class="form-control"></div><div class="col-6"><label class="form-label">Porte</label><select name="size_class" class="form-select"><option value="">—</option><?php foreach(['compact'=>'Compacto','medium'=>'Médio','large'=>'Grande/SUV','pickup'=>'Pickup','motorcycle'=>'Moto','other'=>'Outro'] as $k=>$v):?><option value="<?=$k?>" <?=$vehicle['size_class']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-6"><label class="form-label">Tipo</label><input name="vehicle_type" value="<?=htmlspecialchars($vehicle['vehicle_type']??'')?>" class="form-control"></div><div class="col-6"><label class="form-label">Combustível</label><input name="fuel_type" value="<?=htmlspecialchars($vehicle['fuel_type']??'')?>" class="form-control"></div><div class="col-12"><label class="form-label">Quilometragem</label><input type="number" name="current_odometer" value="<?=htmlspecialchars((string)($vehicle['current_odometer']??''))?>" class="form-control"></div><div class="col-12"><label class="form-label">Cuidados/preferências</label><textarea name="preferred_notes" class="form-control"><?=htmlspecialchars($vehicle['preferred_notes']??'')?></textarea></div><div class="col-12"><input type="hidden" name="vin" value="<?=htmlspecialchars($vehicle['vin']??'')?>"><input type="hidden" name="notes" value="<?=htmlspecialchars($vehicle['notes']??'')?>"><button class="btn btn-primary w-100">Salvar ficha</button></div></form></div></div><div class="card"><div class="card-header"><strong>CRM</strong></div><div class="card-body"><p class="mb-1">Último serviço: <strong><?=$vehicle['last_service_at']?date('d/m/Y',strtotime($vehicle['last_service_at'])):'—'?></strong></p><p class="mb-1">Retorno recomendado: <strong><?=$vehicle['next_recommended_at']?date('d/m/Y',strtotime($vehicle['next_recommended_at'])):'—'?></strong></p><p class="mb-0">Garantia até: <strong><?=$vehicle['warranty_until']?date('d/m/Y',strtotime($vehicle['warranty_until'])):'—'?></strong></p></div></div></div>
<div class="col-lg-8"><div class="card mb-4"><div class="card-header"><strong>Histórico de serviços</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Data</th><th>Serviço</th><th>Box</th><th>Status</th><th>Valor</th><th></th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=date('d/m/Y H:i',strtotime($h['starts_at']))?></td><td><?=htmlspecialchars($h['service_name'])?></td><td><?=htmlspecialchars($h['bay_name']??'—')?></td><td><?=htmlspecialchars($h['status'])?></td><td><?=$h['total_amount']!==null?'R$ '.number_format((float)$h['total_amount'],2,',','.'):'—'?></td><td><a href="/auto/jobs/<?=(int)$h['job_id']?>" class="btn btn-sm btn-outline-primary">Abrir</a></td></tr><?php endforeach;?></tbody></table></div></div><div class="card"><div class="card-header"><strong>Manutenções / recomendações</strong></div><div class="list-group list-group-flush"><?php foreach($maintenance as $m):?><div class="list-group-item"><strong><?=htmlspecialchars($m['title'])?></strong><br><small>Executado <?=date('d/m/Y',strtotime($m['performed_at']))?><?=$m['next_due_at']?' · retorno '.date('d/m/Y',strtotime($m['next_due_at'])):''?><?=$m['warranty_until']?' · garantia '.date('d/m/Y',strtotime($m['warranty_until'])):''?></small></div><?php endforeach;?><?php if(!$maintenance):?><div class="list-group-item text-secondary">Ainda sem histórico técnico.</div><?php endif;?></div></div></div></div>
